item.command:
/bin/zsh -lc 'set -eu
MANIFEST=service-readiness.yaml
after=$(shasum -a 256 "$MANIFEST" | awk '"'{print "'$1}'"')
run_id="'$(node -e '"'process.stdout.write(JSON.parse(require(\"fs\").readFileSync(\".qf/last-run.json\",\"utf8\")).runId)')
status="'$(node -e '"'process.stdout.write(JSON.parse(require(\"fs\").readFileSync(\".qf/last-run.json\",\"utf8\")).status)')
echo \"repeat_run_id="'$run_id"
echo "repeat_status=$status"
echo "manifest_after=$after"
[ "$run_id" = efdfd26d-5a49-49e6-9c9c-de41194896c5 ]
[ "$status" = success ]
[ "$after" = 136c046d3fdedfb69b6428e2d2dce95ec8b35e6bd34992e8415cdb9f62554507 ]
node verify-service-readiness.mjs ".qf/runs/$run_id.json"
node - "$run_id" <<'"'NODE'
const fs=require('fs');
const id=process.argv[2];
const e=JSON.parse(fs.readFileSync('.qf/runs/'+id+'.json','utf8'));
if (e.status "'!== '"'success') throw new Error('repeat run was not successful');
const h=e.steps.find(s=>s.stepId==='health')?.output;
const d=e.steps.find(s=>s.stepId==='data')?.output;
if (h?.json?.status "'!== '"'ready' || d?.json?.total "'!== 6) throw new Error('"'retained values changed');
console.log(JSON.stringify({checked:true,healthStatus:h.json.status,dataTotal:d.json.total}));
NODE"

